function decisionMatrix(opts){
  opts=opts||{};
  var optsList=String(opts.options||'').split(/[\n,，;；]+/).map(function(s){return s.trim();}).filter(Boolean);
  var crit=String(opts.criteria||'').split(/\n/).map(function(s){return s.trim();}).filter(Boolean);
  if(!optsList.length) optsList=['方案 A','方案 B'];
  if(!crit.length) crit=['成本','效果','风险'];
  var L=[];
  L.push('| 方案 | '+crit.join(' | ')+' | 加权合计 |');
  L.push('| --- | '+crit.map(function(){ return '---'; }).join(' | ')+' | --- |');
  for(var j=0;j<optsList.length;j++){
    var cells=[optsList[j]];
    for(var k=0;k<crit.length;k++) cells.push('__');
    cells.push('__');
    L.push('| '+cells.join(' | ')+' |');
  }
  L.push('');
  L.push('> 评分建议 1–5 分；「成本 / 风险」类准则分数越低越好，可反向打分或取倒数后再加权。');
  L.push('');
  L.push('## 权重（合计 100%）');
  for(var m=0;m<crit.length;m++) L.push('- '+crit[m]+'：__%');
  L.push('');
  L.push('## 结论');
  L.push('- 首选：');
  L.push('- 理由：');
  return L.join('\n');
}

var EXPORTS={decisionMatrix:decisionMatrix};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DecisionForgePure = EXPORTS; }
